{"cmd":"python - <<'PY'
import json
from pathlib import Path
from statistics import mean, pstdev

data=json.loads(Path('benchmark/source_data.json').read_text())['national_development']['data']
fields=[
('gdp_per_capita_usd','GDP per capita (USD)'),
('hdi','HDI'),
('freedom_index','Freedom'),
('corruption_perceptions_index','CPI'),
('co2_emissions_per_capita_tons','CO2'),
('military_expenditure_pct_gdp','Military'),
('internet_penetration_pct','Internet')
]
mins={k:1e18 for k,_ in fields}
maxs={k:-1e18 for k,_ in fields}
for r in data:
  for k,_ in fields:
    v=r[k]
    mins[k]=min(mins[k],v)
    maxs[k]=max(maxs[k],v)

def norm_val(k,v):
  a,b=mins[k],maxs[k]
  return 0 if b==a else (v-a)/(b-a)*100

order={'High':0,'Upper-Middle':1,'Lower-Middle':2,'Low':3}
bygrp={g:[] for g in order}
for r in data:
  vals=[norm_val(k,r[k]) for k,_ in fields]
  bygrp[r['income_group']].append((r['country'],vals,r))

# outliers: within group, find top 1 CO2 and bottom 1 freedom perhaps
idx={'GDP':0,'HDI':1,'Freedom':2,'CPI':3,'CO2':4,'Military':5,'Internet':6}
for grp,rows in bygrp.items():
  rows_sorted_co2=sorted(rows,key=lambda t:t[1][idx['CO2']],reverse=True)
  rows_sorted_freedom=sorted(rows,key=lambda t:t[1][idx['Freedom']])
  print(grp,'max CO2',rows_sorted_co2[0][0],rows_sorted_co2[0][2]['co2_emissions_per_capita_tons'])
  print(grp,'min Freedom',rows_sorted_freedom[0][0],rows_sorted_freedom[0][2]['freedom_index'])
PY"}

