import json
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())['national_development']['data']
fields=[
('gdp_per_capita_usd','GDP per capita (USD)'),
('hdi','HDI'),
('freedom_index','Freedom Index (0–100)'),
('corruption_perceptions_index','Corruption Perceptions Index (0–100)'),
('co2_emissions_per_capita_tons','CO₂ emissions (t/cap)'),
('military_expenditure_pct_gdp','Military exp (% GDP)'),
('internet_penetration_pct','Internet penetration (%)')
]
mins={k:1e18 for k,_ in fields}
maxs={k:-1e18 for k,_ in fields}
for r in data:
  for k,_ in fields:
    mins[k]=min(mins[k], r[k])
    maxs[k]=max(maxs[k], r[k])

def norm(k,v):
  a,b=mins[k],maxs[k]
  return 0 if b==a else (v-a)/(b-a)*100

order={'High':0,'Upper-Middle':1,'Lower-Middle':2,'Low':3}
rows=sorted(data,key=lambda r:(order[r['income_group']], r['country']))
blocks=[]
for r in rows:
  vals=[norm(k,r[k]) for k,_ in fields]
  vals_s=",".join(f"{v:.2f}" for v in vals)
  label=r['country']
  blocks.append((r['income_group'], f"  curve \"{label}\"{{{vals_s}}}"))

for grp in ['High','Upper-Middle','Lower-Middle','Low']:
  print('%% '+grp)
  for g,line in blocks:
    if g==grp:
      print(line)
  print()
PY"}
